y identifies each record."},"formative":true,"items":[{"correctCategoryId":"table","id":"table","text":"A structured collection about one subject"},{"correctCategoryId":"record","id":"record","text":"One complete row about an item"},{"correctCategoryId":"field","id":"field","text":"One named column or attribute"},{"correctCategoryId":"pk","id":"pk","text":"A value that uniquely identifies each row"}],"options":[{"label":"Table","value":"table"},{"label":"Record/row","value":"record"},{"label":"Field/column","value":"field"},{"label":"Primary key","value":"pk"}],"prompt":"Match each relational database term to its meaning.","questionId":"foundations-programming-diagnostic:FOUND-PROG-SQL-001","rows":[{"id":"table","label":"A structured collection about one subject"},{"id":"record","label":"One complete row about an item"},{"id":"field","label":"One named column or attribute"},{"id":"pk","label":"A value that uniquely identifies each row"}],"skill":"knowledge","sourceQuestionId":"FOUND-PROG-SQL-001","sourceType":"matching"},"id":"foundations-programming-diagnostic-q-1-FOUND-PROG-SQL-001","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"correctOptionId":"","feedback":{"correct":"WHERE active = true keeps only C01, and SELECT first_name returns Amina.","incorrect":"WHERE active = true keeps only C01, and SELECT first_name returns Amina."},"formative":true,"options":[],"prompt":"Which first name is returned by this query?","questionId":"foundations-programming-diagnostic:FOUND-PROG-SQL-002","skill":"code-reading","sourceQuestionId":"FOUND-PROG-SQL-002","sourceType":"predict-output"},"id":"foundations-programming-diagnostic-q-2-FOUND-PROG-SQL-002","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"","feedback":{"correct":"A WHERE clause filters rows, and the text value Premium is written in quotes.","incorrect":"A WHERE clause filters rows, and the text value Premium is written in quotes."},"formative":true,"options":[],"prompt":"Complete the query so it returns only Premium customers.","questionId":"foundations-programming-diagnostic:FOUND-PROG-SQL-003","skill":"coding-debugging","sourceQuestionId":"FOUND-PROG-SQL-003","sourceType":"code-gap"},"id":"foundations-programming-diagnostic-q-3-FOUND-PROG-SQL-003","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"insert,fields,values","feedback":{"correct":"INSERT INTO names the table, the field list identifies the columns, and VALUES supplies the new row.","incorrect":"INSERT INTO names the table, the field list identifies the columns, and VALUES supplies the new row."},"formative":true,"options":[],"prompt":"Reorder the fragments to form a valid INSERT statement.","questionId":"foundations-programming-diagnostic:FOUND-PROG-SQL-004","skill":"coding-debugging","sourceQuestionId":"FOUND-PROG-SQL-004","sourceType":"code-order"},"id":"foundations-programming-diagnostic-q-4-FOUND-PROG-SQL-004","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"","feedback":{"correct":"WHERE customer_id = 'C02' limits the update to one known record; without it every row would change.","incorrect":"WHERE customer_id = 'C02' limits the update to one known record; without it every row would change."},"formative":true,"options":[],"prompt":"Edit the statement so it updates only customer C02.","questionId":"foundations-programming-diagnostic:FOUND-PROG-SQL-005","skill":"coding-debugging","sourceQuestionId":"FOUND-PROG-SQL-005","sourceType":"code-editor"},"id":"foundations-programming-diagnostic-q-5-FOUND-PROG-SQL-005","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"format":"application/json","text":"```json\n{\n  \"requiresProgrammingLanguage\": true,\n  \"supportedProgrammingLanguages\": [\n    \"python\",\n    \"javascript\",\n    \"csharp\"\n  ],\n  \"resultIntro\": \"This diagnostic shows what you remembered today. Use the topic and skill indicators to choose what to practise next.\"\n}\n```"},"id":"foundations-programming-diagnostic-source-remainder","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"markdown","version":"0.1.0"}],"id":"foundations-programming-diagnostic","metadata":{"activityType":"Diagnostic","detail":"Choose Python, JavaScript or C#, then work through code reading, completion and debugging tasks.","href":"./programming-diagnostic/","status":"available","summary":"Check what you remember about core programming and introductory database concepts.","title":"Programming Diagnostic","topics":["Variables","Selection","Iteration","Functions","Arrays/lists","Debugging","Basic SQL"]},"relationships":{"assets":[],"assignment":"foundations-practice","learningOutcomes":["foundations-lo"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"2.0.0"},{"blocks":[{"content":{"level":2,"text":"Requirements Classification"},"id":"foundations-requirements-classification-title","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Use the result to review how actions, qualities and measurable constraints are expressed in requirements."},"id":"foundations-requirements-classification-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"level":3,"text":"Classify the requirements"},"id":"foundations-requirements-classification-classification-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Northbridge College wants an equipment-loan service for cameras, laptops and audio kits. A functional requirement describes what the solution must do. A non-functional requirement describes a quality, constraint or condition for how it operates."},"id":"foundations-requirements-classification-classification-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"functional","feedback":{"correct":"This describes actions the solution must perform: searching records using three criteria.","incorrect":"This describes actions the solution must perform: searching records using three criteria."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"Students can search available equipment by name, category or collection date.","questionId":"foundations-requirements-classification:FOUND-REQ-001","sourceQuestionId":"FOUND-REQ-001","sourceType":"single"},"id":"foundations-requirements-classification-q-1-FOUND-REQ-001","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"non-functional","feedback":{"correct":"The response-time target is a measurable performance quality rather than a user action.","incorrect":"The response-time target is a measurable performance quality rather than a user action."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"Search results must appear within two seconds for at least 95% of searches during college opening hours.","questionId":"foundations-requirements-classification:FOUND-REQ-002","sourceQuestionId":"FOUND-REQ-002","sourceType":"single"},"id":"foundations-requirements-classification-q-2-FOUND-REQ-002","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"functional","feedback":{"correct":"Reserving an item and selecting a slot are behaviours the solution must provide.","incorrect":"Reserving an item and selecting a slot are behaviours the solution must provide."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"A student can reserve one available item for a selected collection slot.","questionId":"foundations-requirements-classification:FOUND-REQ-003","sourceQuestionId":"FOUND-REQ-003","sourceType":"single"},"id":"foundations-requirements-classification-q-3-FOUND-REQ-003","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"non-functional","feedback":{"correct":"Supported browsers are a compatibility constraint on how the service must operate.","incorrect":"Supported browsers are a compatibility constraint on how the service must operate."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"The service must support the current and previous major versions of Chrome, Firefox, Safari and Edge.","questionId":"foundations-requirements-classification:FOUND-REQ-004","sourceQuestionId":"FOUND-REQ-004","sourceType":"single"},"id":"foundations-requirements-classification-q-4-FOUND-REQ-004","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"functional","feedback":{"correct":"Updating an item's status and storing a reason are system functions.","incorrect":"Updating an item's status and storing a reason are system functions."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"Technicians can mark an item as unavailable and record the reason.","questionId":"foundations-requirements-classification:FOUND-REQ-005","sourceQuestionId":"FOUND-REQ-005","sourceType":"single"},"id":"foundations-requirements-classification-q-5-FOUND-REQ-005","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"non-functional","feedback":{"correct":"This sets a measurable accessibility and usability quality for the interface.","incorrect":"This sets a measurable accessibility and usability quality for the interface."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"The service must remain usable when the page is enlarged to 200% without loss of content or controls.","questionId":"foundations-requirements-classification:FOUND-REQ-006","sourceQuestionId":"FOUND-REQ-006","sourceType":"single"},"id":"foundations-requirements-classification-q-6-FOUND-REQ-006","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"functional","feedback":{"correct":"The requirement specifies data the solution must store when an event occurs.","incorrect":"The requirement specifies data the solution must store when an event occurs."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"When a reservation is confirmed, the service stores the student ID, item ID, collection slot and reservation time.","questionId":"foundations-requirements-classification:FOUND-REQ-007","sourceQuestionId":"FOUND-REQ-007","sourceType":"single"},"id":"foundations-requirements-classification-q-7-FOUND-REQ-007","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"non-functional","feedback":{"correct":"This is an access-control and security constraint on who may see sensitive operational information.","incorrect":"This is an access-control and security constraint on who may see sensitive operational information."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"Only authorised technicians can view the equipment maintenance notes.","questionId":"foundations-requirements-classification:FOUND-REQ-008","sourceQuestionId":"FOUND-REQ-008","sourceType":"single"},"id":"foundations-requirements-classification-q-8-FOUND-REQ-008","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"functional","feedback":{"correct":"Cancellation is a user action. The time rule constrains that function but the main requirement still describes behaviour.","incorrect":"Cancellation is a user action. The time rule constrains that function but the main requirement still describes behaviour."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"A student can cancel a reservation until 30 minutes before its collection slot.","questionId":"foundations-requirements-classification:FOUND-REQ-009","sourceQuestionId":"FOUND-REQ-009","sourceType":"single"},"id":"foundations-requirements-classification-q-9-FOUND-REQ-009","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"non-functional","feedback":{"correct":"This sets a measurable availability condition rather than describing a transaction.","incorrect":"This sets a measurable availability condition rather than describing a transaction."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"The service must be available from 07:00 to 20:00 on teaching days, excluding published maintenance periods.","questionId":"foundations-requirements-classification:FOUND-REQ-010","sourceQuestionId":"FOUND-REQ-010","sourceType":"single"},"id":"foundations-requirements-classification-q-10-FOUND-REQ-010","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"functional","feedback":{"correct":"Displaying an explanatory result after a failed action is behaviour the solution must perform.","incorrect":"Displaying an explanatory result after a failed action is behaviour the solution must perform."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"The service shows a clear reason when a reservation cannot be completed.","questionId":"foundations-requirements-classification:FOUND-REQ-011","sourceQuestionId":"FOUND-REQ-011","sourceType":"single"},"id":"foundations-requirements-classification-q-11-FOUND-REQ-011","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"non-functional","feedback":{"correct":"Encryption in transit is a security condition on how data is handled.","incorrect":"Encryption in transit is a security condition on how data is handled."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"Reservation data must be encrypted while travelling between the browser and the service.","questionId":"foundations-requirements-classification:FOUND-REQ-012","sourceQuestionId":"FOUND-REQ-012","sourceType":"single"},"id":"foundations-requirements-classification-q-12-FOUND-REQ-012","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"functional","feedback":{"correct":"Generating and grouping an overdue-items list is an output the solution must provide.","incorrect":"Generating and grouping an overdue-items list is an output the solution must provide."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"Technicians can produce a list of overdue items grouped by equipment category.","questionId":"foundations-requirements-classification:FOUND-REQ-013","sourceQuestionId":"FOUND-REQ-013","sourceType":"single"},"id":"foundations-requirements-classification-q-13-FOUND-REQ-013","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"non-functional","feedback":{"correct":"This expresses a measurable usability target for completing the reservation process.","incorrect":"This expresses a measurable usability target for completing the reservation process."},"formative":true,"options":[{"id":"functional","label":"Functional"},{"id":"b","label":"Non-functional"}],"prompt":"A first-time student should be able to reserve an available item in no more than five minutes without staff help.","questionId":"foundations-requirements-classification:FOUND-REQ-014","sourceQuestionId":"FOUND-REQ-014","sourceType":"single"},"id":"foundations-requirements-classification-q-14-FOUND-REQ-014","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"level":3,"text":"Requirement quality challenge"},"id":"foundations-requirements-classification-testability-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"A useful requirement gives a tester enough information to decide whether the solution meets it. Decide whether each requirement is testable as written."},"id":"foundations-requirements-classification-testability-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"vague","feedback":{"correct":"Quickly has no shared measurement. A response-time threshold and a defined test condition would make it testable.","incorrect":"Quickly has no shared measurement. A response-time threshold and a defined test condition would make it testable."},"formative":true,"options":[{"id":"testable","label":"Testable as written"},{"id":"vague","label":"Too vague to test reliably"}],"prompt":"The equipment search should load quickly.","questionId":"foundations-requirements-classification:FOUND-REQ-TEST-001","sourceQuestionId":"FOUND-REQ-TEST-001","sourceType":"single"},"id":"foundations-requirements-classification-q-1-FOUND-REQ-TEST-001","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"testable","feedback":{"correct":"The two-second limit and catalogue size give a tester a measurable expected result and condition.","incorrect":"The two-second limit and catalogue size give a tester a measurable expected result and condition."},"formative":true,"options":[{"id":"testable","label":"Testable as written"},{"id":"vague","label":"Too vague to test reliably"}],"prompt":"Search results must be displayed within two seconds when the catalogue contains up to 10,000 items.","questionId":"foundations-requirements-classification:FOUND-REQ-TEST-002","sourceQuestionId":"FOUND-REQ-TEST-002","sourceType":"single"},"id":"foundations-requirements-classification-q-2-FOUND-REQ-TEST-002","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"vague","feedback":{"correct":"Easy is subjective without a defined user group, task and success measure.","incorrect":"Easy is subjective without a defined user group, task and success measure."},"formative":true,"options":[{"id":"testable","label":"Testable as written"},{"id":"vague","label":"Too vague to test reliably"}],"prompt":"The system should be easy for students to use.","questionId":"foundations-requirements-classification:FOUND-REQ-TEST-003","sourceQuestionId":"FOUND-REQ-TEST-003","sourceType":"single"},"id":"foundations-requirements-classification-q-3-FOUND-REQ-TEST-003","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"testable","feedback":{"correct":"The user group, task, time limit, sample size and success threshold can all be observed.","incorrect":"The user group, task, time limit, sample size and success threshold can all be observed."},"formative":true,"options":[{"id":"testable","label":"Testable as written"},{"id":"vague","label":"Too vague to test reliably"}],"prompt":"At least 8 of 10 first-time student testers must complete a reservation within five minutes without staff help.","questionId":"foundations-requirements-classification:FOUND-REQ-TEST-004","sourceQuestionId":"FOUND-REQ-TEST-004","sourceType":"single"},"id":"foundations-requirements-classification-q-4-FOUND-REQ-TEST-004","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"vague","feedback":{"correct":"Work well and modern browsers are undefined, so different testers could reach different conclusions.","incorrect":"Work well and modern browsers are undefined, so different testers could reach different conclusions."},"formative":true,"options":[{"id":"testable","label":"Testable as written"},{"id":"vague","label":"Too vague to test reliably"}],"prompt":"The service must work well in modern browsers.","questionId":"foundations-requirements-classification:FOUND-REQ-TEST-005","sourceQuestionId":"FOUND-REQ-TEST-005","sourceType":"single"},"id":"foundations-requirements-classification-q-5-FOUND-REQ-TEST-005","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"testable","feedback":{"correct":"The browsers, controls and input method are specified, allowing repeatable compatibility and keyboard tests.","incorrect":"The browsers, controls and input method are specified, allowing repeatable compatibility and keyboard tests."},"formative":true,"options":[{"id":"testable","label":"Testable as written"},{"id":"vague","label":"Too vague to test reliably"}],"prompt":"All reservation controls must work in the current versions of Chrome, Firefox, Safari and Edge using keyboard input only.","questionId":"foundations-requirements-classification:FOUND-REQ-TEST-006","sourceQuestionId":"FOUND-REQ-TEST-006","sourceType":"single"},"id":"foundations-requirements-classification-q-6-FOUND-REQ-TEST-006","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"format":"application/json","text":"```json\n{\n  \"resultIntro\": \"Use the result to review how actions, qualities and measurable constraints are expressed in requirements.\"\n}\n```"},"id":"foundations-requirements-classification-source-remainder","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"markdown","version":"0.1.0"}],"id":"foundations-requirements-classification","metadata":{"activityType":"Classification activity","detail":"Classify realistic requirements, then decide whether requirements are testable.","href":"./requirements-classification/","status":"available","summary":"Distinguish what a solution must do from the qualities and constraints it must meet.","title":"Requirements Classification","topics":["Functional requirements","Non-functional requirements","Measurable acceptance criteria"]},"relationships":{"assets":[],"assignment":"foundations-practice","learningOutcomes":["foundations-lo"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"1.0.0"},{"blocks":[{"content":{"level":2,"text":"Problem Decomposition"},"id":"foundations-problem-decomposition-title","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"This result shows how well you connected client needs to manageable technical problems and implementation tasks."},"id":"foundations-problem-decomposition-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"level":3,"text":"Identify major problems"},"id":"foundations-problem-decomposition-major-problems-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Riverside Community Sports Centre needs a digital service where residents create accounts, browse sessions, book or cancel places, and receive confirmation. Staff manage sessions and capacity. The interface must be accessible."},"id":"foundations-problem-decomposition-major-problems-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"accounts,bookings,catalogue,admin","feedback":{"correct":"Major sub-problems group related responsibilities. A colour choice is a detail, while build the whole system is too broad to guide implementation.","incorrect":"Major sub-problems group related responsibilities. A colour choice is a detail, while build the whole system is too broad to guide implementation."},"formative":true,"options":[{"id":"accounts","label":"User accounts"},{"id":"bookings","label":"Bookings and cancellations"},{"id":"catalogue","label":"Session catalogue"},{"id":"admin","label":"Staff administration"},{"id":"colour","label":"Make every button blue"},{"id":"all","label":"Build the whole system"}],"prompt":"Which four are sensible major sub-problems for the overall service?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-001","sourceQuestionId":"FOUND-DECOMP-001","sourceType":"single"},"id":"foundations-problem-decomposition-q-1-FOUND-DECOMP-001","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"capacity","feedback":{"correct":"Checking and updating available places belongs to capacity management, even though booking uses its result.","incorrect":"Checking and updating available places belongs to capacity management, even though booking uses its result."},"formative":true,"options":[{"id":"capacity","label":"Capacity and availability management"},{"id":"accounts","label":"User account creation"},{"id":"notification","label":"Confirmation messages"},{"id":"d","label":"Interface accessibility"}],"prompt":"Which major problem owns checking whether a session still has a free place?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-002","sourceQuestionId":"FOUND-DECOMP-002","sourceType":"single"},"id":"foundations-problem-decomposition-q-2-FOUND-DECOMP-002","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"validate","feedback":{"correct":"Validating a defined set of registration fields is specific enough to implement and test.","incorrect":"Validating a defined set of registration fields is specific enough to implement and test."},"formative":true,"options":[{"id":"validate","label":"Validate required registration fields"},{"id":"build","label":"Build the sports centre service"},{"id":"modern","label":"Make the service modern"},{"id":"everything","label":"Store all possible data"}],"prompt":"Which is a manageable sub-problem for user accounts?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-003","sourceQuestionId":"FOUND-DECOMP-003","sourceType":"single"},"id":"foundations-problem-decomposition-q-3-FOUND-DECOMP-003","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"labels,keyboard,errors","feedback":{"correct":"Labels, keyboard operation and text-based errors create implementable accessibility work. Mandatory drag-and-drop would create a barrier.","incorrect":"Labels, keyboard operation and text-based errors create implementable accessibility work. Mandatory drag-and-drop would create a barrier."},"formative":true,"options":[{"id":"labels","label":"Provide programmatic labels for controls"},{"id":"keyboard","label":"Support keyboard operation"},{"id":"errors","label":"Show errors using text as well as colour"},{"id":"animation","label":"Animate every page transition"},{"id":"mouse","label":"Require drag-and-drop for every booking"}],"prompt":"Which three sub-problems support an accessible booking interface?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-004","sourceQuestionId":"FOUND-DECOMP-004","sourceType":"single"},"id":"foundations-problem-decomposition-q-4-FOUND-DECOMP-004","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"separate","feedback":{"correct":"Recording the booking and delivering a confirmation are related but distinct responsibilities with different failure cases.","incorrect":"Recording the booking and delivering a confirmation are related but distinct responsibilities with different failure cases."},"formative":true,"options":[{"id":"separate","label":"Each has a different responsibility and can fail or be tested independently"},{"id":"same","label":"They must always use the same function"},{"id":"visual","label":"Notifications only affect page colour"},{"id":"database","label":"A booking record never uses data"}],"prompt":"Why should notification delivery be treated as a separate sub-problem from creating a booking record?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-005","sourceQuestionId":"FOUND-DECOMP-005","sourceType":"single"},"id":"foundations-problem-decomposition-q-5-FOUND-DECOMP-005","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"level":3,"text":"Build a problem hierarchy"},"id":"foundations-problem-decomposition-hierarchy-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"A useful hierarchy moves from the overall client problem to a major responsibility and then to smaller technical problems."},"id":"foundations-problem-decomposition-hierarchy-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"overall,major,smaller,task","feedback":{"correct":"The hierarchy narrows from the overall service, through a major responsibility, to a technical problem and a concrete implementation task.","incorrect":"The hierarchy narrows from the overall service, through a major responsibility, to a technical problem and a concrete implementation task."},"formative":true,"options":[],"prompt":"Order these from broadest problem to smallest technical problem.","questionId":"foundations-problem-decomposition:FOUND-DECOMP-HIER-001","sourceQuestionId":"FOUND-DECOMP-HIER-001","sourceType":"order"},"id":"foundations-problem-decomposition-q-1-FOUND-DECOMP-HIER-001","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"answer":{"cancel":"capacity","email":"notifications","filter":"catalogue","password":"accounts","place":"capacity","session":"admin"},"categories":[{"id":"accounts","label":"Accounts and authentication"},{"id":"catalogue","label":"Session catalogue"},{"id":"capacity","label":"Bookings and capacity"},{"id":"admin","label":"Staff administration"},{"id":"notifications","label":"Notifications"}],"feedback":{"correct":"Each smaller problem belongs with the major responsibility whose data and behaviour it directly supports.","incorrect":"Each smaller problem belongs with the major responsibility whose data and behaviour it directly supports."},"formative":true,"items":[{"correctCategoryId":"accounts","id":"password","text":"Check a submitted password against the stored credential"},{"correctCategoryId":"catalogue","id":"filter","text":"Filter sessions by activity type and day"},{"correctCategoryId":"capacity","id":"place","text":"Reduce remaining places after a successful booking"},{"correctCategoryId":"capacity","id":"cancel","text":"Restore a place after a cancellation"},{"correctCategoryId":"admin","id":"session","text":"Allow staff to create a new session"},{"correctCategoryId":"notifications","id":"email","text":"Prepare booking confirmation details"}],"options":[{"label":"Accounts and authentication","value":"accounts"},{"label":"Session catalogue","value":"catalogue"},{"label":"Bookings and capacity","value":"capacity"},{"label":"Staff administration","value":"admin"},{"label":"Notifications","value":"notifications"}],"prompt":"Match each smaller technical problem to its major problem.","questionId":"foundations-problem-decomposition:FOUND-DECOMP-HIER-002","rows":[{"id":"password","label":"Check a submitted password against the stored credential"},{"id":"filter","label":"Filter sessions by activity type and day"},{"id":"place","label":"Reduce remaining places after a successful booking"},{"id":"cancel","label":"Restore a place after a cancellation"},{"id":"session","label":"Allow staff to create a new session"},{"id":"email","label":"Prepare booking confirmation details"}],"sourceQuestionId":"FOUND-DECOMP-HIER-002","sourceType":"matching"},"id":"foundations-problem-decomposition-q-2-FOUND-DECOMP-HIER-002","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"correctOptionId":"details","feedback":{"correct":"Constructing the message data is a smaller problem within the notification responsibility.","incorrect":"Constructing the message data is a smaller problem within the notification responsibility."},"formative":true,"options":[{"id":"details","label":"Build a message containing the user, session, date and time"},{"id":"account","label":"Choose how registration passwords are stored"},{"id":"layout","label":"Design the staff session editor"},{"id":"catalogue","label":"Sort activities by category"}],"prompt":"Which child problem should sit below Send booking confirmation?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-HIER-003","sourceQuestionId":"FOUND-DECOMP-HIER-003","sourceType":"single"},"id":"foundations-problem-decomposition-q-3-FOUND-DECOMP-HIER-003","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"trace","feedback":{"correct":"A hierarchy provides traceability from a broad need to manageable technical work without replacing the requirement itself.","incorrect":"A hierarchy provides traceability from a broad need to manageable technical work without replacing the requirement itself."},"formative":true,"options":[{"id":"trace","label":"It shows how detailed implementation work contributes to a larger client need"},{"id":"hide","label":"It hides technical decisions from developers"},{"id":"replace","label":"It replaces requirements entirely"},{"id":"grade","label":"It guarantees a particular assessment grade"}],"prompt":"What is the best reason to show parent and child problems?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-HIER-004","sourceQuestionId":"FOUND-DECOMP-HIER-004","sourceType":"single"},"id":"foundations-problem-decomposition-q-4-FOUND-DECOMP-HIER-004","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"level":3,"text":"Poor versus effective decomposition"},"id":"foundations-problem-decomposition-quality-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Effective decomposition produces problems that are clear enough to assign, implement and test."},"id":"foundations-problem-decomposition-quality-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"effective","feedback":{"correct":"The effective version names distinct problems with observable outcomes. Build booking system is still the original large problem.","incorrect":"The effective version names distinct problems with observable outcomes. Build booking system is still the original large problem."},"formative":true,"options":[{"id":"effective","label":"Check session exists; check capacity; check eligibility; create booking; update places; return confirmation"},{"id":"broad","label":"Build booking system"},{"id":"visual","label":"Make booking page nice"},{"id":"mixed","label":"Do database and other things"}],"prompt":"Which decomposition is more useful for implementing a booking?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-QUALITY-001","sourceQuestionId":"FOUND-DECOMP-QUALITY-001","sourceType":"single"},"id":"foundations-problem-decomposition-q-1-FOUND-DECOMP-QUALITY-001","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"specific,testable,manageable","feedback":{"correct":"A useful sub-problem has a clear boundary, a checkable outcome and a manageable scope.","incorrect":"A useful sub-problem has a clear boundary, a checkable outcome and a manageable scope."},"formative":true,"options":[{"id":"specific","label":"It has a specific responsibility"},{"id":"testable","label":"Its outcome can be tested"},{"id":"manageable","label":"It is small enough to implement"},{"id":"vague","label":"It uses broad wording such as sort everything out"},{"id":"overlap","label":"It duplicates several unrelated responsibilities"}],"prompt":"Which three qualities make a sub-problem useful to a developer?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-QUALITY-002","sourceQuestionId":"FOUND-DECOMP-QUALITY-002","sourceType":"single"},"id":"foundations-problem-decomposition-q-2-FOUND-DECOMP-QUALITY-002","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"mixed","feedback":{"correct":"The phrase hides separate responsibilities such as reading sessions, creating bookings and updating capacity.","incorrect":"The phrase hides separate responsibilities such as reading sessions, creating bookings and updating capacity."},"formative":true,"options":[{"id":"mixed","label":"It groups unrelated data operations and does not identify the records or behaviours needed"},{"id":"database","label":"Databases cannot be decomposed"},{"id":"short","label":"The wording is too short"},{"id":"code","label":"Developers should not write code"}],"prompt":"Why is Create all database code a weak sub-problem?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-QUALITY-003","sourceQuestionId":"FOUND-DECOMP-QUALITY-003","sourceType":"single"},"id":"foundations-problem-decomposition-q-3-FOUND-DECOMP-QUALITY-003","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"clear","feedback":{"correct":"The revision identifies the trigger, the required data and the hand-off to delivery.","incorrect":"The revision identifies the trigger, the required data and the hand-off to delivery."},"formative":true,"options":[{"id":"clear","label":"Build confirmation data and request delivery after a successful booking"},{"id":"all","label":"Send every possible message"},{"id":"later","label":"Deal with notifications later"},{"id":"system","label":"Make notification system"}],"prompt":"Which revision gives Send notifications a clearer boundary?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-QUALITY-004","sourceQuestionId":"FOUND-DECOMP-QUALITY-004","sourceType":"single"},"id":"foundations-problem-decomposition-q-4-FOUND-DECOMP-QUALITY-004","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"level":3,"text":"Map a requirement to implementation problems"},"id":"foundations-problem-decomposition-requirement-mapping-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Requirement: A resident can book an available session, and the service must prevent the session exceeding its capacity."},"id":"foundations-problem-decomposition-requirement-mapping-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"identify,capacity,record,update","feedback":{"correct":"The four selected problems directly support a valid booking and enforce capacity. Footer colour and payroll are outside this requirement.","incorrect":"The four selected problems directly support a valid booking and enforce capacity. Footer colour and payroll are outside this requirement."},"formative":true,"options":[{"id":"identify","label":"Identify the resident and selected session"},{"id":"capacity","label":"Check remaining capacity"},{"id":"record","label":"Create the booking record"},{"id":"update","label":"Update remaining places safely"},{"id":"colour","label":"Choose the footer colour"},{"id":"payroll","label":"Calculate staff payroll"}],"prompt":"Which four technical problems are directly needed for this requirement?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-MAP-001","sourceQuestionId":"FOUND-DECOMP-MAP-001","sourceType":"single"},"id":"foundations-problem-decomposition-q-1-FOUND-DECOMP-MAP-001","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"find,check,create,decrease,confirm","feedback":{"correct":"The service must find and validate the session before writing changes, then return confirmation after the booking succeeds.","incorrect":"The service must find and validate the session before writing changes, then return confirmation after the booking succeeds."},"formative":true,"options":[],"prompt":"Order the main booking checks and updates into a sensible processing sequence.","questionId":"foundations-problem-decomposition:FOUND-DECOMP-MAP-002","sourceQuestionId":"FOUND-DECOMP-MAP-002","sourceType":"order"},"id":"foundations-problem-decomposition-q-2-FOUND-DECOMP-MAP-002","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"answer":{"check":"read","confirm":"response","record":"insert","validation":"unique"},"categories":[{"id":"read","label":"Read remaining_places for the session"},{"id":"insert","label":"Insert resident_id and session_id into Bookings"},{"id":"unique","label":"Check for an existing resident/session pair"},{"id":"response","label":"Build a response with booking ID and session details"}],"feedback":{"correct":"Each implementation task is a concrete way to solve its technical problem while keeping traceability to the requirement.","incorrect":"Each implementation task is a concrete way to solve its technical problem while keeping traceability to the requirement."},"formative":true,"items":[{"correctCategoryId":"read","id":"check","text":"Check remaining capacity"},{"correctCategoryId":"insert","id":"record","text":"Create the booking record"},{"correctCategoryId":"unique","id":"validation","text":"Reject a duplicate booking"},{"correctCategoryId":"response","id":"confirm","text":"Return confirmation"}],"options":[{"label":"Read remaining_places for the session","value":"read"},{"label":"Insert resident_id and session_id into Bookings","value":"insert"},{"label":"Check for an existing resident/session pair","value":"unique"},{"label":"Build a response with booking ID and session details","value":"response"}],"prompt":"Match each technical problem to a possible implementation task.","questionId":"foundations-problem-decomposition:FOUND-DECOMP-MAP-003","rows":[{"id":"check","label":"Check remaining capacity"},{"id":"record","label":"Create the booking record"},{"id":"validation","label":"Reject a duplicate booking"},{"id":"confirm","label":"Return confirmation"}],"sourceQuestionId":"FOUND-DECOMP-MAP-003","sourceType":"matching"},"id":"foundations-problem-decomposition-q-3-FOUND-DECOMP-MAP-003","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"correctOptionId":"cases","feedback":{"correct":"The mapped problems reveal testable decisions such as no capacity, duplicate booking and successful confirmation.","incorrect":"The mapped problems reveal testable decisions such as no capacity, duplicate booking and successful confirmation."},"formative":true,"options":[{"id":"cases","label":"Each technical problem suggests focused checks and expected outcomes"},{"id":"none","label":"Testing no longer needs requirements"},{"id":"automatic","label":"Every test becomes automated"},{"id":"guarantee","label":"Defects become impossible"}],"prompt":"How does this mapping help later testing?","questionId":"foundations-problem-decomposition:FOUND-DECOMP-MAP-004","sourceQuestionId":"FOUND-DECOMP-MAP-004","sourceType":"single"},"id":"foundations-problem-decomposition-q-4-FOUND-DECOMP-MAP-004","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"format":"application/json","text":"```json\n{\n  \"resultIntro\": \"This result shows how well you connected client needs to manageable technical problems and implementation tasks.\"\n}\n```"},"id":"foundations-problem-decomposition-source-remainder","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"markdown","version":"0.1.0"}],"id":"foundations-problem-decomposition","metadata":{"activityType":"Multi-stage scenario","detail":"Work through sub-problems, hierarchy, decomposition quality and requirement mapping.","href":"./problem-decomposition/","status":"available","summary":"Break a complex client problem into manageable technical problems and implementation tasks.","title":"Problem Decomposition","topics":["Sub-problems","Problem hierarchy","Implementation tasks","Requirement mapping"]},"relationships":{"assets":[],"assignment":"foundations-practice","learningOutcomes":["foundations-lo"],"questions":[]},"schema":"lp.content.activity","schemaVersion":"0.1.0","version":"1.0.0"},{"blocks":[{"content":{"level":2,"text":"Data Design Knowledge Check"},"id":"foundations-data-design-title","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Use this summary to identify which data-design building blocks need more practice before designing a larger solution."},"id":"foundations-data-design-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"level":3,"text":"Fields, records and tables"},"id":"foundations-data-design-data-structure-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Northbridge College stores information about students, clubs and club memberships. Begin with the structure of a relational dataset."},"id":"foundations-data-design-data-structure-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"answer":{"entity":"entity","field":"field","record":"record","table":"table"},"categories":[{"id":"field","label":"Field"},{"id":"record","label":"Record"},{"id":"table","label":"Table"},{"id":"entity","label":"Entity"}],"feedback":{"correct":"A field stores one attribute, a record combines fields for one instance, a table holds consistent records and an entity is the concept represented.","incorrect":"A field stores one attribute, a record combines fields for one instance, a table holds consistent records and an entity is the concept represented."},"formative":true,"items":[{"correctCategoryId":"field","id":"field","text":"email"},{"correctCategoryId":"record","id":"record","text":"S104, Amina Shah, true"},{"correctCategoryId":"table","id":"table","text":"All student records with the same columns"},{"correctCategoryId":"entity","id":"entity","text":"The real-world Student concept being described"}],"options":[{"label":"Field","value":"field"},{"label":"Record","value":"record"},{"label":"Table","value":"table"},{"label":"Entity","value":"entity"}],"prompt":"Match each data term to the example.","questionId":"foundations-data-design:FOUND-DATA-001","rows":[{"id":"field","label":"email"},{"id":"record","label":"S104, Amina Shah, true"},{"id":"table","label":"All student records with the same columns"},{"id":"entity","label":"The real-world Student concept being described"}],"sourceQuestionId":"FOUND-DATA-001","sourceType":"matching"},"id":"foundations-data-design-q-1-FOUND-DATA-001","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"classification","version":"0.1.0"},{"content":{"correctOptionId":"row","feedback":{"correct":"A record is one complete row about one instance, such as one club.","incorrect":"A record is one complete row about one instance, such as one club."},"formative":true,"options":[{"id":"row","label":"One row containing all stored values for club C12"},{"id":"column","label":"The weekly_fee column"},{"id":"table","label":"The complete Clubs table"},{"id":"rule","label":"The rule that capacity must be positive"}],"prompt":"Which description is a record?","questionId":"foundations-data-design:FOUND-DATA-002","sourceQuestionId":"FOUND-DATA-002","sourceType":"single"},"id":"foundations-data-design-q-2-FOUND-DATA-002","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"consistent","feedback":{"correct":"A consistent schema lets the solution interpret, validate and query each record reliably.","incorrect":"A consistent schema lets the solution interpret, validate and query each record reliably."},"formative":true,"options":[{"id":"consistent","label":"It keeps the structure consistent for storage, validation and processing"},{"id":"names","label":"It guarantees every value is unique"},{"id":"size","label":"It makes all text the same length"},{"id":"security","label":"It automatically encrypts the data"}],"prompt":"Why should every record in a table use the same defined fields?","questionId":"foundations-data-design:FOUND-DATA-003","sourceQuestionId":"FOUND-DATA-003","sourceType":"single"},"id":"foundations-data-design-q-3-FOUND-DATA-003","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"joined","feedback":{"correct":"joined_on is concise, meaningful and follows a predictable lowercase underscore convention. Other conventions can also work when applied consistently.","incorrect":"joined_on is concise, meaningful and follows a predictable lowercase underscore convention. Other conventions can also work when applied consistently."},"formative":true,"options":[{"id":"joined","label":"joined_on"},{"id":"space","label":"Joined On Date!!!"},{"id":"x","label":"x1"},{"id":"mixed","label":"jOiNeDdAtE"}],"prompt":"Which name follows a clear, consistent field naming convention?","questionId":"foundations-data-design:FOUND-DATA-004","sourceQuestionId":"FOUND-DATA-004","sourceType":"single"},"id":"foundations-data-design-q-4-FOUND-DATA-004","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"level":3,"text":"Data types and field design"},"id":"foundations-data-design-data-types-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Choose conceptual data types that suit the meaning and operations required by each field."},"id":"foundations-data-design-data-types-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"paragraph","version":"0.1.0"},{"content":{"correctOptionId":"text","feedback":{"correct":"The ID contains a letter and leading zeroes, and it is an identifier rather than a value used in arithmetic.","incorrect":"The ID contains a letter and leading zeroes, and it is an identifier rather than a value used in arithmetic."},"formative":true,"options":[{"id":"text","label":"String/Text"},{"id":"integer","label":"Integer"},{"id":"decimal","label":"Decimal"},{"id":"boolean","label":"Boolean"}],"prompt":"Which conceptual type best fits student_id values such as S00107?","questionId":"foundations-data-design:FOUND-DATA-TYPE-001","sourceQuestionId":"FOUND-DATA-TYPE-001","sourceType":"single"},"id":"foundations-data-design-q-1-FOUND-DATA-TYPE-001","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"integer","feedback":{"correct":"Capacity is a count of whole places, so an integer supports comparison and arithmetic.","incorrect":"Capacity is a count of whole places, so an integer supports comparison and arithmetic."},"formative":true,"options":[{"id":"integer","label":"Integer"},{"id":"text","label":"String/Text"},{"id":"date","label":"Date"},{"id":"boolean","label":"Boolean"}],"prompt":"Which conceptual type best fits a club capacity of 24 places?","questionId":"foundations-data-design:FOUND-DATA-TYPE-002","sourceQuestionId":"FOUND-DATA-TYPE-002","sourceType":"single"},"id":"foundations-data-design-q-2-FOUND-DATA-TYPE-002","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"decimal","feedback":{"correct":"A decimal type represents values with a fractional part. Financial systems may use a dedicated fixed-precision money representation.","incorrect":"A decimal type represents values with a fractional part. Financial systems may use a dedicated fixed-precision money representation."},"formative":true,"options":[{"id":"decimal","label":"Decimal"},{"id":"integer","label":"Integer"},{"id":"boolean","label":"Boolean"},{"id":"date","label":"Date"}],"prompt":"Which conceptual type best fits a weekly fee of 7.50?","questionId":"foundations-data-design:FOUND-DATA-TYPE-003","sourceQuestionId":"FOUND-DATA-TYPE-003","sourceType":"single"},"id":"foundations-data-design-q-3-FOUND-DATA-TYPE-003","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"boolean","feedback":{"correct":"A two-state active flag maps naturally to true or false.","incorrect":"A two-state active flag maps naturally to true or false."},"formative":true,"options":[{"id":"boolean","label":"Boolean"},{"id":"description","label":"Long text"},{"id":"decimal","label":"Decimal"},{"id":"date","label":"Date"}],"prompt":"Which conceptual type best fits whether a membership is active?","questionId":"foundations-data-design:FOUND-DATA-TYPE-004","sourceQuestionId":"FOUND-DATA-TYPE-004","sourceType":"single"},"id":"foundations-data-design-q-4-FOUND-DATA-TYPE-004","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"correctOptionId":"quality","feedback":{"correct":"A justified length supports validation, storage planning and interface design, but it does not create uniqueness or required status.","incorrect":"A justified length supports validation, storage planning and interface design, but it does not create uniqueness or required status."},"formative":true,"options":[{"id":"quality","label":"It documents the expected data and prevents unexpectedly large values"},{"id":"unique","label":"It makes every club name unique"},{"id":"type","label":"It converts the name into a number"},{"id":"required","label":"It makes the field optional"}],"prompt":"Why set a sensible maximum length for club_name?","questionId":"foundations-data-design:FOUND-DATA-TYPE-005","sourceQuestionId":"FOUND-DATA-TYPE-005","sourceType":"single"},"id":"foundations-data-design-q-5-FOUND-DATA-TYPE-005","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"single-choice","version":"0.1.0"},{"content":{"level":3,"text":"Keys and relationships"},"id":"foundations-data-design-keys-relationships-h","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"0.1.0","type":"heading","version":"0.1.0"},{"content":{"text":"Use the accessible entity representation to identify keys and the relationships created by a membership record."},"id":"foundations-data-design-keys-relationships-intro","metadata":{},"relationships":{},"schema":"lp.content.block","schemaVersion":"